import { Tweet } from './Tweet';
import { Box, Stack, HStack } from 'styled-system/jsx';
import { Heading } from '~/components/ui/heading';
import { Text } from '~/components/ui/text';
import { Link } from '~/components/ui/link';
import type { PrunedTweet } from '~/utils/prune-tweets';

interface TweetOrLinkProps {
  url: string;
  tweet: PrunedTweet | null;
  useEnglishName: boolean;
  showBox?: boolean;
  borderStyle?: 'default' | 'subtle';
  bg?: string;
  t?: (key: string) => string;
}

export function TweetOrLink({
  url,
  tweet,
  useEnglishName,
  showBox = true,
  borderStyle = 'default',
  bg,
  t
}: TweetOrLinkProps) {
  if (!tweet) {
    return (
      <Link href={url} target="_blank" fontSize="sm">
        {t ? `${t('bluebird.monthlySummary.viewTweet')} →` : 'View Tweet →'}
      </Link>
    );
  }

  const tweetElement = <Tweet tweet={tweet} quoted hideBottom useEnglishName={useEnglishName} />;

  if (!showBox) {
    return tweetElement;
  }

  return (
    <Box
      border="1px solid"
      borderColor={`border.${borderStyle}`}
      borderRadius="md"
      maxW="600px"
      p="3"
      bg={bg}
    >
      {tweetElement}
    </Box>
  );
}

interface TabContentSectionProps {
  items: Array<{
    title: string;
    description: string;
    tweet_url?: string[];
  }>;
  language: string;
  getTweetFromUrl: (url: string) => PrunedTweet | null;
  type: 'event' | 'topic';
  t?: (key: string) => string;
}

export function TabContentSection({
  items,
  language,
  getTweetFromUrl,
  type,
  t
}: TabContentSectionProps) {
  return (
    <Stack gap="4">
      {items.map((item, idx) => (
        <Box
          key={`${type}-${idx}-${language}`}
          borderLeft="2px solid"
          borderLeftColor={type === 'topic' ? 'blue.7' : 'border.default'}
          pl="4"
        >
          <Heading size="md" mb="1">
            {item.title}
          </Heading>
          <Text mb="3" color="fg.muted">
            {item.description}
          </Text>
          {item.tweet_url && item.tweet_url.length > 0 && (
            <Stack gap="2" mt="3">
              {item.tweet_url.map((url, urlIdx) => {
                const tweet = getTweetFromUrl(url);
                return (
                  <TweetOrLink
                    key={`${type}-tweet-${idx}-${urlIdx}-${language}`}
                    url={url}
                    tweet={tweet}
                    useEnglishName={language === 'en'}
                    t={t}
                  />
                );
              })}
            </Stack>
          )}
        </Box>
      ))}
    </Stack>
  );
}

interface CharacterTweetProps {
  featuredTweet: {
    tweet_url: string;
    date?: string;
  };
  tweet: PrunedTweet | null;
  useEnglishName: boolean;
  t?: (key: string) => string;
}

export function CharacterTweet({ featuredTweet, tweet, useEnglishName, t }: CharacterTweetProps) {
  if (!tweet) {
    return (
      <HStack gap="2" fontSize="sm">
        <Text color="fg.muted">{featuredTweet.date}</Text>
        <Link href={featuredTweet.tweet_url} target="_blank">
          {t ? t('bluebird.monthlySummary.viewTweet') : 'View'} →
        </Link>
      </HStack>
    );
  }

  return (
    <Box border="1px solid" borderColor="border.subtle" borderRadius="md" p="3" bg="bg.default">
      <Tweet tweet={tweet} quoted hideBottom useEnglishName={useEnglishName} />
    </Box>
  );
}
